async function ownerHousing(){try{const {hs,vs}=await ownerData();hs.sort((a,b)=>housingShort(a).localeCompare(housingShort(b),'es',{numeric:true}));$('#main').innerHTML=`<section class="hero"><h1>Mis viviendas</h1><p>${hs.length===1?'1 vivienda asociada':`${hs.length} viviendas asociadas`} a tu usuario.</p></section><div class="owner-list">${hs.map(h=>ownerHousingCard(h,vs)).join('')||'<div class="card empty">No tienes viviendas asignadas.</div>'}</div>`;document.querySelectorAll('.owner-housing-vehicles').forEach(b=>b.onclick=()=>{state.cache.ownerHousingFilter=b.dataset.id;go('ownerVehicles')});document.querySelectorAll('.owner-housing-add').forEach(b=>b.onclick=()=>ownerAddVehicle(b.dataset.id))}catch(e){err(e)}}
