async function ownerQr(v){if(v.Tipo==='Moto'){toast('Las motos se controlan por matrícula y no utilizan QR.',true);return}const available=v.Estado==='Activo'&&['1','2'].includes(String(v.Slot||''))&&v.QR_Estado==='Activo'&&!!v.QR_Token;$('#main').innerHTML=`<div class="head"><h1>QR de mi vehículo</h1><button class="secondary" id="owner-qr-back">Volver</button></div><div class="grid"><div class="card result ${available?'':'bad'}"><span class="status ${available?'':'bad'}">${esc(v.Estado)} · QR ${esc(v.QR_Estado)}</span>${qrVehicleIdentityHtml(v)}<div class="details" style="margin-top:.8rem"><div><small>Estado vehículo</small>${esc(v.Estado)}</div><div><small>Slot</small>${esc(v.Slot||'Liberado')}</div></div></div><div class="card" style="text-align:center"><h2>Código QR</h2>${available?`<div id="owner-qr-code" style="display:inline-block"></div><p class="muted">Este QR identifica al vehículo y valida la matrícula habitual o la temporal vigente.</p><div class="actions" style="justify-content:center;margin-top:1rem"><button id="owner-qr-download">Descargar PNG</button><button class="secondary" id="owner-qr-print">Imprimir</button></div>`:`<div class="message bad">Este QR no está disponible.</div>`}</div></div>`;$('#owner-qr-back').onclick=ownerVehicles;if(!available)return;$('#owner-qr-print').onclick=()=>window.print();$('#owner-qr-download').disabled=true;try{await ensureQr();const size=qrSize();new QRCode($('#owner-qr-code'),{text:qrTarget(v.QR_Token),width:size,height:size,correctLevel:QRCode.CorrectLevel.L});$('#owner-qr-download').disabled=false}catch(e){$('#owner-qr-code').innerHTML=`<div class="message bad">${esc(e.message)}</div>`}$('#owner-qr-download').onclick=()=>{const box=$('#owner-qr-code'),canvas=box.querySelector('canvas'),img=box.querySelector('img'),url=canvas?canvas.toDataURL('image/png'):img?.src;if(!url){toast('No se pudo preparar el QR.',true);return}const a=document.createElement('a');a.href=url;a.download='QR_'+String(v.MatriculaHabitual||'vehiculo').replace(/[^A-Za-z0-9]/g,'')+'.png';document.body.appendChild(a);a.click();a.remove()}}
function ownerEditor(v){const host=$('#owner-editor');host.innerHTML=`<form class="card form" id="owner-form"><h2 class="wide">Editar vehículo</h2>${[['MatriculaHabitual','Matrícula habitual','text'],['Marca','Marca','text'],['Modelo','Modelo','text']].map(f=>field(f,v)).join('')}<div class="field"><label>Tipo</label><input value="${esc(v.Tipo||'—')}" disabled></div><input type="hidden" name="Tipo" value="${esc(v.Tipo)}"><input type="hidden" name="Estado" value="${esc(v.Estado)}"><input type="hidden" name="Slot" value="${esc(v.Tipo==='Moto'?'':v.Slot)}"><div class="message wide">Los períodos de matrícula temporal se gestionan desde <b>Temporales</b>. Para cambiar entre moto y vehículo con slot, contacta con administración.</div><div class="wide actions"><button>Guardar</button><button type="button" class="secondary" id="owner-cancel">Cancelar</button></div></form>`;$('#owner-cancel').onclick=()=>host.innerHTML='';$('#owner-form').onsubmit=async e=>{e.preventDefault();const b=e.submitter;busy(b);const data=Object.fromEntries(new FormData(e.target));data.ID_Vehiculo=v.ID_Vehiculo;data.ModoPropietario='1';try{await call('saveVehicle',data);toast('Vehículo actualizado.');await ownerData(true);ownerVehicles()}catch(x){toast(x.message,true);busy(b,false)}};host.scrollIntoView({behavior:'smooth'})}
function ownerAddVehicle(preselectedHousing=''){const host=$('#owner-editor')||$('#main'),hs=(state.cache.ownerHousing||[]).filter(h=>h.Estado==='Activa'),vs=state.cache.ownerVehicles||[];if(!hs.length){toast('No hay viviendas activas disponibles.',true);return}const selected=hs.some(h=>h.ID_Vivienda===preselectedHousing)?preselectedHousing:hs[0].ID_Vivienda,housingOptions=hs.map(h=>`<option value="${esc(h.ID_Vivienda)}" ${h.ID_Vivienda===selected?'selected':''}>${esc(housingShort(h))}</option>`).join('');host.innerHTML=`<form class="card form" id="owner-add-form"><h2 class="wide">Añadir vehículo</h2><div class="message wide">Puedes registrar el vehículo sin asignarle slot. Después podrás rotarlo desde <b>Asignar slot</b>.</div><div class="field wide"><label>Vivienda</label><select name="ID_Vivienda" id="owner-add-housing" required>${housingOptions}</select></div><div class="field"><label>Tipo</label><select name="Tipo" id="owner-add-type">${['Particular','Empresa','Alquiler','Moto','Otro'].map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field"><label>Slot inicial</label><select name="Slot" id="owner-add-slot"></select><span id="owner-slot-help" class="subtle"></span></div>${[['MatriculaHabitual','Matrícula habitual','text'],['Marca','Marca','text'],['Modelo','Modelo','text']].map(f=>field(f,{})).join('')}<div class="wide actions"><button>Crear vehículo</button><button type="button" class="secondary" id="owner-add-cancel">Cancelar</button></div></form>`;const refresh=()=>{const hid=$('#owner-add-housing').value,type=$('#owner-add-type').value,slot=$('#owner-add-slot'),used=vs.filter(v=>v.ID_Vivienda===hid&&v.Estado==='Activo'&&v.Tipo!=='Moto'&&['1','2'].includes(String(v.Slot||''))).map(v=>String(v.Slot)),free=['1','2'].filter(x=>!used.includes(x));if(type==='Moto'){slot.innerHTML='<option value="">No aplica</option>';slot.disabled=true;$('#owner-slot-help').textContent='Las motos no ocupan slot.'}else{slot.disabled=false;slot.innerHTML='<option value="">Sin slot por ahora</option>'+free.map(x=>`<option value="${x}">Slot ${x}</option>`).join('');$('#owner-slot-help').textContent=free.length?'Puedes dejarlo sin slot o asignar uno libre.':'Los dos slots están ocupados. Regístralo sin slot y luego podrás rotarlo.'}};$('#owner-add-housing').onchange=refresh;$('#owner-add-type').onchange=refresh;refresh();$('#owner-add-cancel').onclick=()=>ownerVehicles();$('#owner-add-form').onsubmit=async e=>{e.preventDefault();const b=e.submitter;busy(b);const data=Object.fromEntries(new FormData(e.target));if($('#owner-add-slot').disabled)data.Slot='';data.ModoPropietario='1';try{await call('saveVehicle',data);toast(data.Tipo==='Moto'?'Moto registrada.':data.Slot?'Vehículo creado con slot y QR asociado.':'Vehículo registrado sin slot.');await ownerData(true);ownerVehicles()}catch(x){toast(x.message,true);busy(b,false)}};host.scrollIntoView({behavior:'smooth'})}
async function ownerGiveLow(v){if(!confirm(`¿Dar de baja ${v.MatriculaHabitual}? Se liberará el slot si corresponde y el QR quedará revocado.`))return;try{await call('saveVehicle',{ID_Vehiculo:v.ID_Vehiculo,MatriculaHabitual:v.MatriculaHabitual,Marca:v.Marca,Modelo:v.Modelo,Tipo:v.Tipo,Estado:'Baja',ModoPropietario:'1'});toast('Vehículo dado de baja.');await ownerData(true);ownerVehicles()}catch(e){err(e)}}
async function ownerRequest(v,type){const existing=(state.cache.ownerRequests||[]).some(r=>r.ID_Vehiculo===v.ID_Vehiculo&&r.Tipo===type&&r.Estado==='Pendiente');if(existing){toast('Ya existe una solicitud pendiente de este tipo.',true);return}if(type==='REACTIVACION_VEHICULO'&&!['Suspendido','Baja'].includes(v.Estado)){toast('Este vehículo no está en un estado que permita solicitar reactivación.',true);return}if(type==='RENOVACION_QR'&&(v.Tipo==='Moto'||v.Estado!=='Activo'||!['1','2'].includes(String(v.Slot||''))||v.QR_Estado!=='Revocado')){toast(v.Tipo==='Moto'?'Las motos no utilizan QR.':!v.Slot?'El vehículo no tiene slot asignado.':'Solo se puede solicitar renovación cuando el QR está revocado.',true);return}const titulo=type==='REACTIVACION_VEHICULO'?'Solicitar reactivación':'Solicitar renovación QR',detalle=type==='REACTIVACION_VEHICULO'?(v.Tipo==='Moto'?'La moto se reactivará sin slot.':'El vehículo se reactivará registrado y después podrás asignarle un slot desde Mis vehículos.'):'Al aprobar, el QR revocado será reemplazado por uno nuevo.';if(!confirm(`${titulo} para ${v.MatriculaHabitual}?\n\n${detalle}`))return;const motivo=prompt(type==='REACTIVACION_VEHICULO'?'Motivo de la reactivación (opcional):':'Motivo de la renovación QR (opcional):','');if(motivo===null)return;try{await call('createRequest',{ID_Vehiculo:v.ID_Vehiculo,Tipo:type,Motivo:motivo});toast(type==='REACTIVACION_VEHICULO'?'Solicitud de reactivación registrada.':'Solicitud de renovación QR registrada.');await ownerData(true);ownerVehicles()}catch(e){err(e)}}
async function ownerIncidents(){try{const {hs,incs}=await ownerData(),map=ownerHousingMap(hs);$('#main').innerHTML=`<div class="head"><h1>Mis incidencias</h1></div><div class="filterbar"><div class="field filter-search"><label>Buscar</label><input id="owner-inc-search" class="search" placeholder="Matrícula, tipo, estado..."></div><div class="field"><label>Estado</label><select id="owner-inc-state"><option value="">Todas</option><option>Abierta</option><option>Cerrada</option></select></div><div class="field"><label>Agrupar por</label><select id="owner-inc-group"><option value="plate" selected>Matrícula</option><option value="type">Tipo de incidencia</option><option value="none">Sin agrupar</option></select></div><span class="count" id="owner-inc-count"></span></div><div id="owner-inc-list"></div>`;const plateOf=r=>r.MatriculaObservada||r.MatriculaHabitualOrigen||r.MatriculaHabitualVehiculo||'SIN MATRÍCULA';const rowHtml=r=>`<div class="owner-list-row"><div class="owner-list-main"><div class="owner-list-title"><span>${esc(r.Tipo)}</span><span class="status ${r.Estado==='Cerrada'?'':'bad'}">${esc(r.Estado||'Abierta')}</span></div><div class="owner-list-meta"><span>${esc(plateOf(r))}</span><span>${esc(recordHousingLabel(r,map[r.ID_Vivienda]))}</span><span>${esc(shortDateTime(r.FechaHora))}</span><span>ITV: ${esc(r.ITV_Vencida||'No verificado')}</span></div>${r.Descripcion?`<div>${esc(r.Descripcion)}</div>`:''}${r.Foto?`<div class="subtle"><a href="${esc(r.Foto)}" target="_blank" rel="noopener">Ver fotografía</a></div>`:''}${r.Estado==='Cerrada'?`<div class="message owner-resolution"><b>Resolución:</b> ${esc(r.AccionCierre||'Sin actuación')}<br><b>Comentario:</b> ${esc(r.ComentarioCierre||'—')}<br>${r.NombreUsuarioCierre||r.UsuarioCierre?`<span class="subtle">Resuelta por ${esc(r.NombreUsuarioCierre||r.UsuarioCierre)} · ${esc(shortDateTime(r.FechaCierre))}</span>`:''}</div>`:''}</div></div>`;const render=()=>{const q=$('#owner-inc-search').value.trim().toLowerCase(),st=$('#owner-inc-state').value,group=$('#owner-inc-group').value,rows=incs.filter(r=>(!st||r.Estado===st)&&Object.values(r).join(' ').toLowerCase().includes(q)).sort((a,b)=>String(b.FechaHora||'').localeCompare(String(a.FechaHora||'')));$('#owner-inc-count').textContent=`${rows.length} incidencia${rows.length===1?'':'s'}`;const host=$('#owner-inc-list');if(!rows.length){host.innerHTML='<div class="card empty">No tienes incidencias asociadas a tus viviendas o vehículos.</div>';return}if(group==='none'){host.innerHTML=`<div class="owner-list">${rows.map(rowHtml).join('')}</div>`;return}const groups={};rows.forEach(r=>{const key=group==='type'?(r.Tipo||'Sin tipo'):plateOf(r);(groups[key]||(groups[key]=[])).push(r)});const keys=Object.keys(groups).sort((a,b)=>groups[b].length-groups[a].length||a.localeCompare(b,'es',{numeric:true}));host.innerHTML=keys.map(key=>`<section class="owner-group"><div class="owner-group-head"><h2>${esc(key)}</h2><span class="count">${groups[key].length} incidencia${groups[key].length===1?'':'s'}</span></div><div class="owner-list">${groups[key].sort((a,b)=>String(b.FechaHora).localeCompare(String(a.FechaHora))).map(rowHtml).join('')}</div></section>`).join('')};$('#owner-inc-search').oninput=render;$('#owner-inc-state').onchange=render;$('#owner-inc-group').onchange=render;render()}catch(e){err(e)}}

function ownerAssignSlot(v,allVehicles){if(v.Tipo==='Moto'||v.Estado!=='Activo'){toast('Este vehículo no puede ocupar un slot.',true);return}const same=(allVehicles||[]).filter(x=>x.ID_Vivienda===v.ID_Vivienda&&x.ID_Vehiculo!==v.ID_Vehiculo&&x.Estado==='Activo'&&x.Tipo!=='Moto'),bySlot={};same.forEach(x=>{if(['1','2'].includes(String(x.Slot||'')))bySlot[String(x.Slot)]=x});const host=$('#owner-editor');host.innerHTML=`<form class="card form" id="owner-slot-form"><h2 class="wide">${v.Slot?'Cambiar':'Asignar'} slot · ${esc(v.MatriculaHabitual)}</h2><div class="field wide"><label>Selecciona slot</label><select name="Slot" id="owner-slot-select"><option value="1" ${String(v.Slot)==='1'?'selected':''}>Slot 1${bySlot['1']?' · actualmente '+esc(bySlot['1'].MatriculaHabitual):' · libre'}</option><option value="2" ${String(v.Slot)==='2'?'selected':''}>Slot 2${bySlot['2']?' · actualmente '+esc(bySlot['2'].MatriculaHabitual):' · libre'}</option></select></div><div class="message wide" id="owner-slot-info"></div><div class="wide actions"><button>Confirmar asignación</button><button type="button" class="secondary" id="owner-slot-cancel">Cancelar</button></div></form>`;const select=$('#owner-slot-select'),info=$('#owner-slot-info');const refresh=()=>{const occ=bySlot[select.value];info.innerHTML=occ?`El Slot ${esc(select.value)} está asignado a <b>${esc(occ.MatriculaHabitual)}</b>. Al confirmar, ese vehículo quedará sin slot y ${esc(v.MatriculaHabitual)} pasará a utilizar <b>el mismo QR asociado a ese slot</b>.`:`El Slot ${esc(select.value)} está libre. Se asociará a ${esc(v.MatriculaHabitual)}.`};select.onchange=refresh;refresh();$('#owner-slot-cancel').onclick=()=>host.innerHTML='';$('#owner-slot-form').onsubmit=async e=>{e.preventDefault();const slot=select.value,occ=bySlot[slot];if(occ&&!confirm(`El Slot ${slot} está asignado a ${occ.MatriculaHabitual}.\n\n¿Liberarlo y asignarlo a ${v.MatriculaHabitual}?\n\nEl QR del slot se mantiene.`))return;const b=e.submitter;busy(b);try{const out=await call('assignVehicleSlot',{ID_Vehiculo:v.ID_Vehiculo,Slot:slot,confirmReplace:!!occ});toast(out.message||'Slot actualizado.');await ownerData(true);ownerVehicles()}catch(x){toast(x.message,true);busy(b,false)}};host.scrollIntoView({behavior:'smooth'})}

async function ownerReleaseSlot(v){if(!v.Slot)return;if(!confirm(`¿Liberar el Slot ${v.Slot} de ${v.MatriculaHabitual}?\n\nEl vehículo quedará registrado pero sin QR asociado.`))return;try{await call('releaseVehicleSlot',{ID_Vehiculo:v.ID_Vehiculo});toast('Slot liberado.');await ownerData(true);ownerVehicles()}catch(e){err(e)}}

function ownerReplaceVehicle(v){const host=$('#owner-editor');host.innerHTML=`<form class="card form" id="owner-replace-form"><h2 class="wide">Reemplazar vehículo · ${esc(v.MatriculaHabitual)}</h2><div class="message wide">El vehículo actual quedará de baja. ${v.Slot?`El nuevo conservará el Slot ${esc(v.Slot)} y el mismo QR asociado.`:'El nuevo quedará registrado sin slot.'}</div><div class="field"><label>Matrícula nueva</label><input name="MatriculaHabitual" required></div><div class="field"><label>Tipo</label><select name="Tipo">${['Particular','Empresa','Alquiler','Moto','Otro'].map(x=>`<option ${x===v.Tipo?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Marca <span class="muted">(opcional)</span></label><input name="Marca"></div><div class="field"><label>Modelo <span class="muted">(opcional)</span></label><input name="Modelo"></div><div class="wide actions"><button>Reemplazar vehículo</button><button type="button" class="secondary" id="owner-replace-cancel">Cancelar</button></div></form>`;$('#owner-replace-cancel').onclick=()=>host.innerHTML='';$('#owner-replace-form').onsubmit=async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));if(!confirm(`¿Confirmar el reemplazo de ${v.MatriculaHabitual} por ${data.MatriculaHabitual}?`))return;const b=e.submitter;busy(b);try{await call('replaceVehicle',Object.assign(data,{ID_Vehiculo:v.ID_Vehiculo}));toast('Vehículo reemplazado.');await ownerData(true);ownerVehicles()}catch(x){toast(x.message,true);busy(b,false)}};host.scrollIntoView({behavior:'smooth'})}
function ownerLongStayRequest(v){const existing=(state.cache.ownerRequests||[]).some(r=>r.ID_Vehiculo===v.ID_Vehiculo&&r.Tipo==='PERMANENCIA_PROLONGADA'&&r.Estado==='Pendiente');if(existing){toast('Ya existe una solicitud de permanencia pendiente para este vehículo.',true);return}const host=$('#owner-editor');host.innerHTML=`<form class="card form" id="owner-longstay-form"><h2 class="wide">Solicitar permanencia prolongada · ${esc(v.MatriculaHabitual)}</h2><div class="message wide">La solicitud debe ser aprobada por administración. Una vez aprobada, Control verá que la permanencia está autorizada durante el período indicado.</div><div class="field"><label>Fecha inicio</label><input type="date" name="FechaInicio" required></div><div class="field"><label>Fecha fin prevista</label><input type="date" name="FechaFin" required></div><div class="field"><label>Motivo de permanencia</label><select name="MotivoTipo" id="owner-longstay-type" required><option value="">Seleccionar…</option><option>Viaje prolongado</option><option>Vehículo inmovilizado</option><option>Otro</option></select></div><div class="field wide"><label id="owner-longstay-detail-label">Detalle del motivo <span class="muted">(opcional)</span></label><textarea name="MotivoDetalle" id="owner-longstay-detail" placeholder="Podés agregar un detalle si lo considerás necesario."></textarea></div><div class="wide actions"><button>Enviar solicitud</button><button type="button" class="secondary" id="owner-longstay-cancel">Cancelar</button></div></form>`;const type=$('#owner-longstay-type'),detail=$('#owner-longstay-detail'),label=$('#owner-longstay-detail-label');const refresh=()=>{const required=type.value==='Otro';detail.required=required;label.innerHTML=required?'Detalle del motivo <b>(obligatorio)</b>':'Detalle del motivo <span class="muted">(opcional)</span>';detail.placeholder=required?'Indica el motivo de la permanencia.':'Podés agregar un detalle si lo considerás necesario.'};type.onchange=refresh;refresh();$('#owner-longstay-cancel').onclick=()=>host.innerHTML='';$('#owner-longstay-form').onsubmit=async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target)),motivoTipo=(data.MotivoTipo||'').trim(),motivoDetalle=(data.MotivoDetalle||'').trim();if(motivoTipo==='Otro'&&!motivoDetalle){toast('Para Otro tenés que indicar el detalle del motivo.',true);detail.focus();return}data.Motivo=`${motivoTipo}${motivoDetalle?' · '+motivoDetalle:''}`;delete data.MotivoTipo;delete data.MotivoDetalle;if(data.FechaFin<data.FechaInicio){toast('La fecha fin no puede ser anterior a la fecha inicio.',true);return}const b=e.submitter;busy(b);try{await call('createRequest',Object.assign(data,{ID_Vehiculo:v.ID_Vehiculo,Tipo:'PERMANENCIA_PROLONGADA'}));toast('Solicitud de permanencia enviada a administración.');await ownerData(true);ownerVehicles()}catch(x){toast(x.message,true);busy(b,false)}};host.scrollIntoView({behavior:'smooth'})}
function profile(){
  $('#main').innerHTML=`<form class="card form" id="profile-form"><h1 class="wide">Mis datos</h1><div class="field"><label>Email</label><input value="${esc(state.user.Email)}" disabled></div><div class="field"><label>Nombre</label><input name="Nombre" value="${esc(state.user.Nombre)}" required></div><div class="wide"><button>Guardar cambios</button></div></form><form class="card form" id="change-password-form" style="margin-top:1rem"><h2 class="wide">Cambiar contraseña</h2><div class="field"><label>Contraseña actual</label><input name="currentPassword" type="password" autocomplete="current-password" required></div><div class="field"><label>Nueva contraseña</label><input name="newPassword" type="password" minlength="8" autocomplete="new-password" required></div><div class="wide"><span class="muted" style="font-size:.8rem">Mínimo 8 caracteres, con una letra y un número.</span></div><div class="wide"><button>Cambiar contraseña</button></div></form>`;
  $('#profile-form').onsubmit=async e=>{e.preventDefault();try{state.user=await call('updateProfile',Object.fromEntries(new FormData(e.target)));toast('Datos actualizados.');shell();go('profile')}catch(x){err(x)}};
  $('#change-password-form').onsubmit=async e=>{e.preventDefault();const b=e.submitter;busy(b);try{await call('changePassword',Object.fromEntries(new FormData(e.target)));e.target.reset();toast('Contraseña actualizada.')}catch(x){toast(x.message,true)}finally{busy(b,false)}}
}

// 1.2.11.2 UX overrides
async function ownerVehicles(){try{
  const {hs,vs,reqs,incs}=await ownerData(),ui=viewUiState('ownerVehicles');state.cache.ownerRequests=reqs;
  const houseMap=ownerHousingMap(hs),houses=[...hs].sort((a,b)=>housingShort(a).localeCompare(housingShort(b),'es',{numeric:true}));
  $('#main').innerHTML=`<div class="head"><div><h1>Mis vehículos</h1><div class="muted">Vehículos registrados ordenados por vivienda. Puedes rotar qué vehículo ocupa cada slot.</div></div></div><div class="filterbar"><div class="field"><label>Clase</label><select id="ov-class"><option value="">Todos</option><option>Vehículo</option><option>Moto</option></select></div><div class="field"><label>Slot</label><select id="ov-slot"><option value="">Todos</option><option>Con slot</option><option>Sin slot</option></select></div><div class="field"><label>Solicitudes</label><select id="ov-req"><option value="">Todas</option><option value="Con pendientes">Con pendientes</option><option value="Sin pendientes">Sin pendientes</option></select></div><div class="field"><label>Incidencias</label><select id="ov-inc"><option value="">Todas</option><option value="Con pendientes">Con pendientes</option><option value="Sin pendientes">Sin pendientes</option></select></div><button type="button" class="secondary" id="ov-clear">Limpiar</button><span class="count" id="ov-count"></span></div><div id="owner-editor"></div><div id="owner-vehicles-list"></div>`;
  const els={cl:$('#ov-class'),slot:$('#ov-slot'),req:$('#ov-req'),inc:$('#ov-inc')};els.cl.value=ui.cl||'';els.slot.value=ui.slot||'';els.req.value=ui.req||'';els.inc.value=ui.inc||'';
  const pendingReq=id=>reqs.some(r=>r.ID_Vehiculo===id&&r.Estado==='Pendiente'),pendingInc=id=>incs.some(r=>r.ID_Vehiculo===id&&r.Estado!=='Cerrada');
  const render=()=>{saveViewUiState('ownerVehicles',{cl:els.cl.value,slot:els.slot.value,req:els.req.value,inc:els.inc.value});let count=0;const html=houses.map(h=>{let rows=vs.filter(v=>v.ID_Vivienda===h.ID_Vivienda);rows=rows.filter(v=>{const cls=v.Tipo==='Moto'?'Moto':'Vehículo',hasSlot=v.Tipo!=='Moto'&&['1','2'].includes(String(v.Slot||'')),pr=pendingReq(v.ID_Vehiculo),pi=pendingInc(v.ID_Vehiculo);return (!els.cl.value||cls===els.cl.value)&&(!els.slot.value||(els.slot.value==='Con slot'?hasSlot:!hasSlot))&&(!els.req.value||(els.req.value==='Con pendientes'?pr:!pr))&&(!els.inc.value||(els.inc.value==='Con pendientes'?pi:!pi))});if(!rows.length)return '';count+=rows.length;const vehicleRows=rows.filter(v=>v.Tipo!=='Moto'),motoRows=rows.filter(v=>v.Tipo==='Moto'),slots=vs.filter(v=>v.ID_Vivienda===h.ID_Vivienda&&v.Estado==='Activo'&&v.Tipo!=='Moto'&&['1','2'].includes(String(v.Slot||''))).length;const group=(label,items)=>items.length?`<div class="owner-group"><div class="owner-group-head"><h3>${label}</h3><span class="count">${items.length}</span></div><div class="owner-list flat-list">${items.map(v=>ownerVehicle(v,vs.indexOf(v),h)).join('')}</div></div>`:'';return `<section class="owner-section"><div class="head"><div><h2>${esc(housingShort(h))}</h2><span class="muted">${slots}/2 slots ocupados · ${vs.filter(v=>v.ID_Vivienda===h.ID_Vivienda).length} registrados</span></div>${h.Estado==='Activa'?`<button class="owner-add" data-id="${esc(h.ID_Vivienda)}">＋ Añadir vehículo</button>`:''}</div>${group('Vehículos',vehicleRows)}${group('Motos',motoRows)}</section>`}).join('');$('#ov-count').textContent=`${count} vehículo${count===1?'':'s'}`;$('#owner-vehicles-list').innerHTML=html||'<div class="card empty">No hay vehículos que coincidan con los filtros.</div>';bindOwnerVehicleActions(vs)};
  const bind=()=>Object.values(els).forEach(x=>x.onchange=render);bind();$('#ov-clear').onclick=()=>{Object.values(els).forEach(x=>x.value='');render()};render();
}catch(e){err(e)}}
function bindOwnerVehicleActions(vs){document.querySelectorAll('.owner-add').forEach(b=>b.onclick=()=>ownerAddVehicle(b.dataset.id));document.querySelectorAll('.owner-edit').forEach(b=>b.onclick=()=>ownerEditor(vs[b.dataset.i]));document.querySelectorAll('.owner-qr').forEach(b=>b.onclick=()=>ownerQr(vs[b.dataset.i]));document.querySelectorAll('.owner-periods').forEach(b=>b.onclick=()=>temporaryPeriodsPanel(vs[b.dataset.i],ownerVehicles));document.querySelectorAll('.owner-low').forEach(b=>b.onclick=()=>ownerGiveLow(vs[b.dataset.i]));document.querySelectorAll('.owner-reactivate').forEach(b=>b.onclick=()=>ownerRequest(vs[b.dataset.i],'REACTIVACION_VEHICULO'));document.querySelectorAll('.owner-renew').forEach(b=>b.onclick=()=>ownerRequest(vs[b.dataset.i],'RENOVACION_QR'));document.querySelectorAll('.owner-longstay').forEach(b=>b.onclick=()=>ownerLongStayRequest(vs[b.dataset.i]));document.querySelectorAll('.owner-slot').forEach(b=>b.onclick=()=>ownerAssignSlot(vs[b.dataset.i],vs));document.querySelectorAll('.owner-release-slot').forEach(b=>b.onclick=()=>ownerReleaseSlot(vs[b.dataset.i]));document.querySelectorAll('.owner-replace').forEach(b=>b.onclick=()=>ownerReplaceVehicle(vs[b.dataset.i]))}

